cd "$(dirname "$0")"
while pgrep -f "run_viagem.sh" >/dev/null; do sleep 20; done
cat run_viagem.out
ffmpeg -v error -y -framerate 30 -i v1/%04d.png -framerate 30 -i v2/%04d.png -framerate 30 -i v3/%04d.png -i trilha_viagem.wav -i noticia.mp3 -filter_complex "[0]scale=1080:1920:flags=lanczos,format=yuv420p,settb=1/30[a];[1]scale=1080:1920:flags=lanczos,format=yuv420p,settb=1/30[b];[2]scale=1080:1920:flags=lanczos,format=yuv420p,settb=1/30[c];[a][b]xfade=transition=fade:duration=0.5:offset=3.0[ab];[ab][c]xfade=transition=fade:duration=0.5:offset=5.5,drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text='Litoral do Maranhão':fontsize=46:fontcolor=white:shadowcolor=black@0.6:shadowx=2:shadowy=2:x=(w-tw)/2:y=150:enable='between(t,0.4,2.9)',drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text='Rumo a Imperatriz':fontsize=46:fontcolor=white:shadowcolor=black@0.6:shadowx=2:shadowy=2:x=(w-tw)/2:y=150:enable='between(t,3.4,5.6)',drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text='Imperatriz · BR-010':fontsize=46:fontcolor=white:shadowcolor=black@0.6:shadowx=2:shadowy=2:x=(w-tw)/2:y=150:enable='between(t,6.0,8.6)',subtitles=viagem.srt:force_style='FontName=DejaVu Sans,Fontsize=10,Bold=1,PrimaryColour=&H00FFFFFF,OutlineColour=&H00202020,BorderStyle=1,Outline=2,Shadow=1,Alignment=2,MarginV=24'[v];[3]volume=0.6[t];[4]adelay=8900|8900,volume=1.6[f];[t][f]amix=inputs=2:normalize=0,loudnorm=I=-14:TP=-1.5,aresample=48000[o]" -map "[v]" -map "[o]" -c:v libx264 -crf 18 -preset medium -pix_fmt yuv420p -c:a aac -b:a 192k -shortest viagem_sem_foto.mp4
ffmpeg -v error -y -i viagem_sem_foto.mp4 -i ../fotos/card.mp4 -filter_complex "[0:a]aresample=48000[a0];[1:a]aresample=48000[a1];[0:v]fps=30,setsar=1[v0];[1:v]fps=30,setsar=1[v1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]" -map "[v]" -map "[a]" -c:v libx264 -crf 18 -pix_fmt yuv420p -c:a aac -b:a 192k -movflags +faststart guara-litoral-imperatriz.mp4
ls -la guara-litoral-imperatriz.mp4; ffprobe -v error -show_entries format=duration -of csv=p=0 guara-litoral-imperatriz.mp4
for s in 1.5 4.5 7 15; do ffmpeg -v error -y -ss $s -i guara-litoral-imperatriz.mp4 -frames:v 1 -vf scale=270:-1 vv$s.jpg; done
ffmpeg -v error -y -i vv1.5.jpg -i vv4.5.jpg -i vv7.jpg -i vv15.jpg -filter_complex hstack=4 viagem_strip.jpg
